#include <iostream>
#include <vector>
#include <utility>

void selectionSort(std::vector<int>& arr) {
    const size_t n = arr.size();
    for (size_t i = 0; i < n - 1; ++i) {
        size_t smallest = i;
        for (size_t j = i + 1; j < n; ++j) {
            if (arr[j] < arr[smallest]) {
                smallest = j;
            }
        }
        std::swap(arr[i], arr[smallest]);
    }
}

int main() {
    std::vector<int> data = {72, 34, 88, 14, 32, 12, 34, 77, 56, 83};
    selectionSort(data);
    for (size_t i = 0; i < data.size(); ++i) {
        std::cout << data[i] << (i + 1 == data.size() ? "" : " ");
    }
    std::cout << "\n";
    return 0;
}

#include <iostream>
#include <vector>

void insertionSort(std::vector<int>& arr) {
    for (size_t i = 1; i < arr.size(); ++i) {
        int insertValue = arr[i];
        size_t moveItem = i;
        while (moveItem > 0 && arr[moveItem - 1] > insertValue) {
            arr[moveItem] = arr[moveItem - 1];
            --moveItem;
        }
        arr[moveItem] = insertValue;
    }
}

int main() {
    std::vector<int> data = {34, 56, 4, 10, 77, 51, 93, 30, 5, 52};
    insertionSort(data);
    for (size_t i = 0; i < data.size(); ++i) {
        std::cout << data[i] << (i + 1 == data.size() ? "" : " ");
    }
    std::cout << "\n";
    return 0;
}
